const originalPhone = String($json.phone || $json.from || $json.senderPhone || $json.customer_phone || $json.normalizedMessage?.from || '').trim();
const digits = originalPhone.replace(/[^0-9]/g, '');
const correlationId = $json.correlationId || $json.normalizedMessage?.correlationId || 'corr_' + Date.now() + '_' + ($execution.id || 'n8n');
return [{ json: { ...$json, originalPhone, phoneDigits: digits, correlationId, workflowExecutionId: String($execution.id || '') } }];

let digits = String($json.phoneDigits || '');
if (digits.startsWith('00')) digits = digits.slice(2);
let normalizedPhone = '';
let status = 'INVALID';
if (!digits) status = 'INVALID';
else if (digits.startsWith('9715') && digits.length === 12) { normalizedPhone = digits; status = 'VALID'; }
else if (digits.startsWith('05') && digits.length === 10) { normalizedPhone = '971' + digits.slice(1); status = 'VALID'; }
else if (digits.startsWith('5') && digits.length === 9) { normalizedPhone = '971' + digits; status = 'VALID'; }
else if (digits.startsWith('971') && !digits.startsWith('9715')) status = 'UNSUPPORTED_COUNTRY';
else if (digits.length > 0 && digits.length < 9) status = 'INCOMPLETE';
else if (!digits.startsWith('971') && !digits.startsWith('0') && !digits.startsWith('5')) status = 'UNSUPPORTED_COUNTRY';
return [{ json: { ...$json, normalizedPhone, phoneStatus: status } }];
